1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"unicode/utf8"
14	)
15	
16	// Check statuses recorded per rule in a report.
17	const (
18		StatusUnchecked   = "未检查"
19		StatusPass        = "通过"
20		StatusDefect      = "发现缺陷"
21		StatusToolMissing = "工具缺失"
22		StatusTimeout     = "超时"
23	)
24	
25	// ReportArtifact identifies the audited artifact by name and content hash.
26	type ReportArtifact struct {
27		Name string `json:"name"`
28		Hash string `json:"hash"`
29	}
30	
31	// ReportRule is one rule together with the invariant check result. The note
32	// carries the original checker description: counterexample evidence for a
33	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
34	// or an optional remark for a passing check. It is empty for reports built
35	// only from invariant booleans.
36	type ReportRule struct {
37		ID          string `json:"id"`
38		Kind        string `json:"kind"`
39		Severity    string `json:"severity"`
40		Invariant   string `json:"invariant"`
41		RequiresABI bool   `json:"requiresABI"`
42		Version     string `json:"version"`
43		Status      string `json:"status"`
44		Note        string `json:"note,omitempty"`
45	}
46	
47	// ReportFinding binds a defect to its artifact, rule, version and evidence.
48	type ReportFinding struct {
49		ArtifactHash string `json:"artifactHash"`
50		RuleID       string `json:"ruleId"`
51		Version      string `json:"version"`
52		Severity     string `json:"severity"`
53		Invariant    string `json:"invariant"`
54		Evidence     string `json:"evidence"`
55	}
56	
57	// Report is the persisted audit result.
58	type Report struct {
59		ReportID string          `json:"reportId"`
60		Artifact ReportArtifact  `json:"artifact"`
61		Rules    []ReportRule    `json:"rules"`
62		Findings []ReportFinding `json:"findings"`
63	}
64	
65	// wireArtifact is the JSON shape of an artifact in an audit submission.
66	type wireArtifact struct {
67		Name     string `json:"name"`
68		ABI      string `json:"abi"`
69		Bytecode string `json:"bytecode"`
70		Source   string `json:"source"`
71	}
72	
73	// wireRule is the JSON shape of a rule in an audit submission.
74	type wireRule struct {
75		ID          string `json:"id"`
76		Kind        string `json:"kind"`
77		Severity    string `json:"severity"`
78		Invariant   string `json:"invariant"`
79		RequiresABI bool   `json:"requiresABI"`
80		Version     string `json:"version"`
81	}
82	
83	// CheckRecord is one imported per-rule check result: the artifact hash and
84	// rule version it was produced against, the conclusion status, and the
85	// original checker note (counterexample, tool or deadline remark).
86	type CheckRecord struct {
87		ArtifactHash string
88		RuleID       string
89		Version      string
90		Status       string
91		Note         string
92	}
93	
94	// wireCheck is the JSON shape of one entry in the checks array.
95	type wireCheck struct {
96		ArtifactHash string `json:"artifactHash"`
97		RuleID       string `json:"ruleId"`
98		Version      string `json:"version"`
99		Status       string `json:"status"`
100		Note         string `json:"note"`
101	}
102	
103	// wireInput is the JSON object accepted by the audit command.
104	type wireInput struct {
105		Artifact   wireArtifact               `json:"artifact"`
106		Rules      []wireRule                 `json:"rules"`
107		Invariants map[string]json.RawMessage `json:"invariants"`
108		Checks     []wireCheck                `json:"checks"`
109	}
110	
111	// submissionShape is the fixed-field shape of an audit submission: the agreed
112	// spellings at the top level and inside the artifact, every rule and every
113	// check record. The invariants object is a fixed top-level member but has no
114	// nested shape, so it passes through untouched: invariant names are
115	// user-defined rather than fixed fields, and "Inv" and "inv" stay two
116	// independent invariants and a padded name is not trimmed.
117	var submissionShape = fixedShape{
118		keys: []string{"artifact", "rules", "invariants", "checks"},
119		objects: map[string]fixedShape{
120			"artifact": {keys: []string{"name", "abi", "bytecode", "source"}},
121		},
122		arrays: map[string]fixedShape{
123			"rules":  {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}},
124			"checks": {keys: []string{"artifactHash", "ruleId", "version", "status", "note"}},
125		},
126	}
127	
128	// strictSubmissionJSON rewrites submission bytes to the fixed submission
129	// fields under their agreed spelling; see fixedShape for the recognition
130	// convention shared with the archive read side.
131	func strictSubmissionJSON(data []byte) ([]byte, error) {
132		return strictFixedJSON(data, submissionShape)
133	}
134	
135	// validateFormalCheckStatuses checks the formal "status" member of every
136	// strict check record. The strict rewrite dropped extension members, so the
137	// status seen here is the agreed-spelling one alone: a missing formal status,
138	// a non-string one, or an unsupported value rejects the whole submission
139	// even when an adjacent "StAtus" extension member carried a legal-looking
140	// value. The error names the rule the record is for so the offending entry is
141	// identifiable.
142	func validateFormalCheckStatuses(strict []byte) error {
143		var top struct {
144			Checks []map[string]json.RawMessage `json:"checks"`
145		}
146		if err := json.Unmarshal(strict, &top); err != nil {
147			return errInvalid("invalid JSON: " + err.Error())
148		}
149		for _, rec := range top.Checks {
150			where := "check record"
151			if raw, ok := rec["ruleId"]; ok {
152				var ruleID string
153				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
154					where = "check for rule " + ruleID
155				}
156			}
157			raw, ok := rec["status"]
158			if !ok {
159				return errInvalid(where + ": status is required")
160			}
161			var status string
162			if err := json.Unmarshal(raw, &status); err != nil {
163				return errInvalid(where + ": status must be a string")
164			}
165			if !validCheckStatus(status) {
166				return errInvalid(where + ": unknown status " + status)
167			}
168		}
169		return nil
170	}
171	
172	// validateFormalRequiresABI checks the formal "requiresABI" member of every
173	// strict rule definition. The strict rewrite dropped extension members, so the
174	// value seen here is the agreed-spelling one alone. Decoding the member
175	// straight into a Go bool would turn null into the zero value false: a rule
176	// whose requirement was never actually stated would be recorded as not
177	// needing an ABI, indistinguishable from an explicit false, and could even
178	// produce a defect finding from a false invariant. When the formal member is
179	// present its value must be the JSON boolean true or false — null, a string,
180	// a number, an object or an array rejects the whole submission, whether or
181	// not the artifact carries an ABI and whether or not the rule received any
182	// check conclusion. An omitted member still means false. A case-variant or
183	// whitespace-padded name is extension data and its value, null included,
184	// never reaches this check; it can neither trigger the error nor rescue an
185	// illegal formal value. The error names the rule so the offending entry is
186	// identifiable.
187	func validateFormalRequiresABI(strict []byte) error {
188		var top struct {
189			Rules []map[string]json.RawMessage `json:"rules"`
190		}
191		if err := json.Unmarshal(strict, &top); err != nil {
192			return errInvalid("invalid JSON: " + err.Error())
193		}
194		for _, rule := range top.Rules {
195			where := "rule"
196			if raw, ok := rule["id"]; ok {
197				var id string
198				if err := json.Unmarshal(raw, &id); err == nil && id != "" {
199					where = "rule " + id
200				}
201			}
202			raw, ok := rule["requiresABI"]
203			if !ok {
204				continue
205			}
206			var token any
207			if err := json.Unmarshal(raw, &token); err != nil {
208				return errInvalid(where + ": requiresABI must be a boolean")
209			}
210			if _, isBool := token.(bool); !isBool {
211				return errInvalid(where + ": requiresABI must be a boolean")
212			}
213		}
214		return nil
215	}
216	
217	// ParseAuditInput decodes an audit submission JSON object into domain values.
218	// Invariant values must be JSON booleans; any other type is an error. A formal
219	// requiresABI member on a rule must likewise be a JSON boolean: null or any
220	// non-boolean value rejects the whole submission instead of being read as the
221	// zero value false, while an omitted member still means false. Any JSON
222	// object in the submission that repeats a member name rejects the whole
223	// submission: the decoder keeps only the last value silently, so a repeated
224	// invariant key would choose a conclusion by member order instead of giving
225	// one trustworthy result. A character the decoder would silently rewrite — an
226	// invalid UTF-8 byte, or an unpaired or wrongly ordered surrogate escape in
227	// any member name or string value, including values nested under unknown
228	// extension members — rejects the whole submission as an input error before
229	// any content is hashed, so evidence and hashes always reflect the submitted
230	// bytes rather than a U+FFFD-rewritten copy. Only the fixed fields under their
231	// agreed spelling participate: case variants and whitespace-padded names are
232	// extension data and are ignored, so they can neither override a formal value
233	// nor supply one when the formal member is missing or unsupported. Invariant
234	// names are not fixed fields — they are user-defined, compared case
235	// sensitively and never trimmed.
236	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
237		if charErr := validateJSONCharacters(data); charErr != nil {
238			return Artifact{}, nil, nil, nil, errInvalid(charErr.Error())
239		}
240		if dup := findDuplicateJSONMember(data); dup != nil {
241			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
242		}
243		strict, err := strictSubmissionJSON(data)
244		if err != nil {
245			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
246		}
247		if err := validateFormalCheckStatuses(strict); err != nil {
248			return Artifact{}, nil, nil, nil, err
249		}
250		if err := validateFormalRequiresABI(strict); err != nil {
251			return Artifact{}, nil, nil, nil, err
252		}
253		var in wireInput
254		if err := json.Unmarshal(strict, &in); err != nil {
255			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
256		}
257		invariants := make(map[string]bool, len(in.Invariants))
258		for key, raw := range in.Invariants {
259			// Only JSON true/false is a conclusion. Unmarshalling directly into a
260			// bool would turn null into the zero value false, which would falsely
261			// record a defect; require the token to be a boolean instead.
262			var token any
263			if err := json.Unmarshal(raw, &token); err != nil {
264				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
265			}
266			holds, ok := token.(bool)
267			if !ok {
268				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
269			}
270			invariants[key] = holds
271		}
272		artifact := Artifact{
273			Name:     in.Artifact.Name,
274			ABI:      in.Artifact.ABI,
275			Bytecode: in.Artifact.Bytecode,
276			Source:   in.Artifact.Source,
277		}
278		rules := make([]Rule, 0, len(in.Rules))
279		for _, wr := range in.Rules {
280			rules = append(rules, Rule{
281				ID:          wr.ID,
282				Kind:        wr.Kind,
283				Severity:    wr.Severity,
284				Invariant:   wr.Invariant,
285				RequiresABI: wr.RequiresABI,
286				Version:     wr.Version,
287			})
288		}
289		checks := make([]CheckRecord, 0, len(in.Checks))
290		for _, wc := range in.Checks {
291			checks = append(checks, CheckRecord{
292				ArtifactHash: wc.ArtifactHash,
293				RuleID:       wc.RuleID,
294				Version:      wc.Version,
295				Status:       wc.Status,
296				Note:         wc.Note,
297			})
298		}
299		return artifact, rules, invariants, checks, nil
300	}
301	
302	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
303	// bytecode and source strings contribute; field boundaries are explicit
304	// (length-prefixed) so that different splits never collide. The source is
305	// hashed as a field value, never read from disk, and the name does not
306	// participate.
307	func ArtifactHash(a Artifact) string {
308		h := sha256.New()
309		h.Write([]byte("contractsentinel-artifact-v1\n"))
310		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
311			fmt.Fprintf(h, "%d\n", len(field))
312			h.Write([]byte(field))
313		}
314		sum := h.Sum(nil)
315		return hex.EncodeToString(sum)
316	}
317	
318	// validCheckStatus reports whether status is one of the four recorded check
319	// conclusions.
320	func validCheckStatus(status string) bool {
321		switch status {
322		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
323			return true
324		}
325		return false
326	}
327	
328	// BuildReport evaluates rules against the artifact and invariant values and
329	// imported check records and produces the report to persist. Insufficient
330	// inputs (missing ABI for a rule that requires it, missing bytecode for a
331	// symbolic rule) fail the whole submission and are never recorded as defects.
332	// Imported checks are validated as a whole: unknown rules, duplicate records,
333	// unknown statuses, missing notes, hash or version mismatches, and a rule
334	// receiving both a check record and an invariant boolean all reject the
335	// submission without producing a report.
336	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
337		if artifact.Name == "" {
338			return Report{}, errInvalid("artifact name is required")
339		}
340		hash := ArtifactHash(artifact)
341		seen := make(map[string]bool, len(rules))
342		ruleByID := make(map[string]Rule, len(rules))
343		for _, rule := range rules {
344			if rule.ID == "" {
345				return Report{}, errInvalid("rule id is required")
346			}
347			if rule.Version == "" {
348				return Report{}, errInvalid("rule " + rule.ID + " version is required")
349			}
350			if seen[rule.ID] {
351				return Report{}, errInvalid("duplicate rule id " + rule.ID)
352			}
353			seen[rule.ID] = true
354			ruleByID[rule.ID] = rule
355			if rule.RequiresABI && artifact.ABI == "" {
356				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
357			}
358			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
359				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
360			}
361		}
362		checkByRule := make(map[string]CheckRecord, len(checks))
363		for _, check := range checks {
364			if check.RuleID == "" {
365				return Report{}, errInvalid("check rule id is required")
366			}
367			rule, ok := ruleByID[check.RuleID]
368			if !ok {
369				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
370			}
371			if _, dup := checkByRule[check.RuleID]; dup {
372				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
373			}
374			if check.ArtifactHash != hash {
375				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
376			}
377			if check.Version != rule.Version {
378				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
379			}
380			if !validCheckStatus(check.Status) {
381				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
382			}
383			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
384				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
385			}
386			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
387				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
388			}
389			checkByRule[check.RuleID] = check
390		}
391		report := Report{
392			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
393			Rules:    []ReportRule{},
394			Findings: []ReportFinding{},
395		}
396		for _, rule := range rules {
397			status := StatusUnchecked
398			note := ""
399			if check, ok := checkByRule[rule.ID]; ok {
400				status = check.Status
401				note = check.Note
402			} else {
403				// No imported check: the invariant booleans decide. The verdict
404				// interpretation is shared with the finding-list path in Run.
405				switch checkInvariant(rule, invariants) {
406				case invariantHolds:
407					status = StatusPass
408				case invariantViolated:
409					status = StatusDefect
410				}
411			}
412			report.Rules = append(report.Rules, ReportRule{
413				ID:          rule.ID,
414				Kind:        rule.Kind,
415				Severity:    rule.Severity,
416				Invariant:   rule.Invariant,
417				RequiresABI: rule.RequiresABI,
418				Version:     rule.Version,
419				Status:      status,
420				Note:        note,
421			})
422			if status == StatusDefect {
423				evidence := note
424				if evidence == "" {
425					evidence = invariantEvidence(rule.Invariant)
426				}
427				report.Findings = append(report.Findings, ReportFinding{
428					ArtifactHash: hash,
429					RuleID:       rule.ID,
430					Version:      rule.Version,
431					Severity:     rule.Severity,
432					Invariant:    rule.Invariant,
433					Evidence:     evidence,
434				})
435			}
436		}
437		report.ReportID = ReportID(report)
438		return report, nil
439	}
440	
441	// canonicalRule is the order-independent view of a rule used for the id. The
442	// note is omitted when empty so reports built only from invariant booleans
443	// keep their original ids.
444	type canonicalRule struct {
445		ID          string `json:"id"`
446		Kind        string `json:"kind"`
447		Severity    string `json:"severity"`
448		Invariant   string `json:"invariant"`
449		RequiresABI bool   `json:"requiresABI"`
450		Version     string `json:"version"`
451		Status      string `json:"status"`
452		Note        string `json:"note,omitempty"`
453	}
454	
455	// canonicalFinding is the order-independent view of a finding used for the id.
456	type canonicalFinding struct {
457		ArtifactHash string `json:"artifactHash"`
458		RuleID       string `json:"ruleId"`
459		Version      string `json:"version"`
460		Severity     string `json:"severity"`
461		Invariant    string `json:"invariant"`
462		Evidence     string `json:"evidence"`
463	}
464	
465	// canonicalReport is the deterministic content a report id is computed from.
466	type canonicalReport struct {
467		ArtifactHash string             `json:"artifactHash"`
468		Name         string             `json:"name"`
469		Rules        []canonicalRule    `json:"rules"`
470		Findings     []canonicalFinding `json:"findings"`
471	}
472	
473	// canonicalize renders a report into its order-independent form.
474	func canonicalize(report Report) canonicalReport {
475		cr := canonicalReport{
476			ArtifactHash: report.Artifact.Hash,
477			Name:         report.Artifact.Name,
478		}
479		for _, rule := range report.Rules {
480			cr.Rules = append(cr.Rules, canonicalRule{
481				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
482				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
483				Version: rule.Version, Status: rule.Status, Note: rule.Note,
484			})
485		}
486		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
487		for _, finding := range report.Findings {
488			cr.Findings = append(cr.Findings, canonicalFinding{
489				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
490				Version: finding.Version, Severity: finding.Severity,
491				Invariant: finding.Invariant, Evidence: finding.Evidence,
492			})
493		}
494		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
495		return cr
496	}
497	
498	// ReportID returns the content-addressed identifier of a report. The id binds
499	// the artifact hash, name, complete rule definitions, the invariant value
500	// used by each rule (unchecked and explicit pass are distinct), and the
501	// findings. Rule order, invariant key order and unrelated invariant keys do
502	// not influence it.
503	func ReportID(r Report) string {
504		data, err := json.Marshal(canonicalize(r))
505		if err != nil {
506			panic(err) // canonical values are all strings and bools
507		}
508		sum := sha256.Sum256(data)
509		return hex.EncodeToString(sum[:])
510	}
511	
512	// validateReport checks every archive legality condition against r. It is the
513	// single definition of a legal report: the id and artifact hash are 64
514	// lowercase hex characters, the id matches the content, the artifact name is
515	// present, rule ids are present and unique with non-empty versions, statuses
516	// use the five recorded values, tool-missing and timeout notes are
517	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
518	// artifact hash, version, severity, invariant and evidence match the rule.
519	// The same conditions apply to submissions and to stored archives: a
520	// recomputed id never makes an invalid report legal. fail is errInvalid for
521	// submissions and errCorrupt for stored archives.
522	func validateReport(r Report, fail func(string) error) error {
523		if !validReportID(r.ReportID) {
524			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
525		}
526		if r.Artifact.Name == "" {
527			return fail("report " + r.ReportID + " artifact name is required")
528		}
529		if !validReportID(r.Artifact.Hash) {
530			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
531		}
532		if ReportID(r) != r.ReportID {
533			return fail("report content does not match id " + r.ReportID)
534		}
535		seenRule := make(map[string]bool, len(r.Rules))
536		defectByID := make(map[string]ReportRule)
537		for _, rule := range r.Rules {
538			if rule.ID == "" {
539				return fail("report " + r.ReportID + " has a rule with an empty id")
540			}
541			if seenRule[rule.ID] {
542				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
543			}
544			seenRule[rule.ID] = true
545			if rule.Version == "" {
546				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
547			}
548			switch rule.Status {
549			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
550			default:
551				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
552			}
553			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
554				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
555			}
556			if rule.Status == StatusDefect {
557				defectByID[rule.ID] = rule
558			}
559		}
560		seenFinding := make(map[string]bool, len(r.Findings))
561		for _, f := range r.Findings {
562			if f.RuleID == "" {
563				return fail("report " + r.ReportID + " has a finding with an empty rule id")
564			}
565			rule, ok := defectByID[f.RuleID]
566			if !ok {
567				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
568			}
569			if seenFinding[f.RuleID] {
570				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
571			}
572			seenFinding[f.RuleID] = true
573			if f.ArtifactHash != r.Artifact.Hash {
574				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
575			}
576			if f.Version != rule.Version {
577				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
578			}
579			if f.Severity != rule.Severity {
580				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
581			}
582			if f.Invariant != rule.Invariant {
583				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
584			}
585			wantEvidence := rule.Note
586			if wantEvidence == "" {
587				wantEvidence = invariantEvidence(rule.Invariant)
588			}
589			if f.Evidence != wantEvidence {
590				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
591			}
592		}
593		for id := range defectByID {
594			if !seenFinding[id] {
595				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
596			}
597		}
598		return nil
599	}
600	
601	// validStoredReport validates archive contents.
602	func validStoredReport(r Report) error {
603		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
604	}
605	
606	// validSubmittedReport validates a submission before any store operation.
607	func validSubmittedReport(r Report) error {
608		return validateReport(r, func(msg string) error { return errInvalid(msg) })
609	}
610	
611	// firstInvalidUTF8ByteInString returns the first byte that is not valid UTF-8
612	// inside s. A Go string can carry any bytes, including bytes no JSON text may
613	// contain: json.Marshal (and therefore the canonical marshalling inside
614	// ReportID) silently replaces such a byte with U+FFFD instead of failing, so
615	// neither the id/content check nor the archive round trip can see it.
616	func firstInvalidUTF8ByteInString(s string) (byte, bool) {
617		for i := 0; i < len(s); {
618			r, size := utf8.DecodeRuneInString(s[i:])
619			if r == utf8.RuneError && size == 1 {
620				return s[i], true
621			}
622			i += size
623		}
624		return 0, false
625	}
626	
627	// validateSubmittedText is the in-memory counterpart of the JSON character
628	// gates in ParseAuditInput and loadStoredReport. SaveReport accepts a Report
629	// built directly by a Go caller, whose strings never passed through JSON
630	// decoding; encoding/json marshals such a value without an error while
631	// replacing every invalid UTF-8 byte with U+FFFD, and ReportID computes from
632	// the same rewritten canonical form, so the recomputed id and the
633	// rule/finding correspondence would all match an archive whose text no
634	// longer equals what the caller handed over. Every caller-supplied string is
635	// therefore checked on the raw object — reportId, artifact name and hash,
636	// each rule definition field and status note, and each finding binding field
637	// and evidence — independently of which rules produced defects and of
638	// whether the report carries any finding at all. The rejection is an input
639	// error naming the exact field, with the array position of rules and
640	// findings, and it runs before any filesystem operation.
641	func validateSubmittedText(r Report) error {
642		check := func(field, value string) error {
643			if b, bad := firstInvalidUTF8ByteInString(value); bad {
644				return errInvalid(fmt.Sprintf("invalid UTF-8 byte 0x%02x in report field %s", b, field))
645			}
646			return nil
647		}
648		if err := check("reportId", r.ReportID); err != nil {
649			return err
650		}
651		if err := check("artifact.name", r.Artifact.Name); err != nil {
652			return err
653		}
654		if err := check("artifact.hash", r.Artifact.Hash); err != nil {
655			return err
656		}
657		ruleFields := []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
658		for i, rule := range r.Rules {
659			values := []string{rule.ID, rule.Kind, rule.Severity, rule.Invariant, rule.Version, rule.Status, rule.Note}
660			for j, value := range values {
661				if err := check(fmt.Sprintf("rules[%d].%s", i, ruleFields[j]), value); err != nil {
662					return err
663				}
664			}
665		}
666		findingFields := []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}
667		for i, finding := range r.Findings {
668			values := []string{finding.ArtifactHash, finding.RuleID, finding.Version, finding.Severity, finding.Invariant, finding.Evidence}
669			for j, value := range values {
670				if err := check(fmt.Sprintf("findings[%d].%s", i, findingFields[j]), value); err != nil {
671					return err
672				}
673			}
674		}
675		return nil
676	}
677	
678	// duplicateArchiveError classifies an archive that repeats a JSON member as
679	// corrupt and names the requested report id, the decoded member name and the
680	// object carrying it (with array position and rule id when applicable).
681	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
682		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
683	}
684	
685	// characterArchiveError classifies an archive whose bytes are not legal JSON
686	// text — an invalid UTF-8 byte anywhere, or an unpaired / wrongly ordered
687	// surrogate escape inside any member name or string value, including unknown
688	// extension members — as corrupt and names the requested report id together
689	// with the precise byte offset, line/column and JSON path. It is the
690	// read-side counterpart of the submission gate in ParseAuditInput: the decode
691	// below would otherwise replace both problems with U+FFFD and could accept a
692	// rewritten archive whose id and rule/finding evidence happened to match.
693	func characterArchiveError(id string, charErr *charEncodingError) error {
694		return errCorrupt("report " + id + " archive is corrupt: " + charErr.Error())
695	}
696	
697	// reportShape is the fixed-field shape of a stored report archive: the agreed
698	// spellings at the top level and inside the artifact, every rule and every
699	// finding. The trusted content of a report is carried by these fixed fields
700	// alone; case variants, whitespace-padded names and unknown members are
701	// extension data and never reach the decoder.
702	var reportShape = fixedShape{
703		keys: []string{"reportId", "artifact", "rules", "findings"},
704		objects: map[string]fixedShape{
705			"artifact": {keys: []string{"name", "hash"}},
706		},
707		arrays: map[string]fixedShape{
708			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
709			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
710		},
711	}
712	
713	// strictReportJSON rewrites archive bytes to the fixed report fields under
714	// their original spelling; see fixedShape for the recognition convention
715	// shared with the submission side.
716	func strictReportJSON(data []byte) ([]byte, error) {
717		return strictFixedJSON(data, reportShape)
718	}
719	
720	// validateArchiveRequiresABI is the read-side counterpart of the submission
721	// check in validateFormalRequiresABI. A ReportRule.RequiresABI is a Go bool,
722	// so decoding the strict archive straight into Report turns a formal null
723	// member into the zero value false: an archive that wrote "requiresABI":null
724	// would read byte-for-byte like one that wrote false, the recomputed id and
725	// the rule/finding correspondence would all pass on that laundered value, and
726	// a diff could even compare it as an unchanged rule. When the formal member
727	// is present its value must therefore be the JSON boolean true or false;
728	// null, a string, a number, an object or an array makes the whole archive
729	// corrupt, independently of the rule's check status and of whether it has a
730	// finding — the offending rule is never skipped and no partial report is
731	// returned. An omitted member still means false. The strict rewrite dropped
732	// extension members, so a case-variant or whitespace-padded name is invisible
733	// here: a boolean it carries neither supplies nor rescues the formal value,
734	// and a null it carries never reaches this check.
735	func validateArchiveRequiresABI(strict []byte, id string) error {
736		var top struct {
737			Rules []map[string]json.RawMessage `json:"rules"`
738		}
739		if err := json.Unmarshal(strict, &top); err != nil {
740			return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
741		}
742		for _, rule := range top.Rules {
743			where := "rule"
744			if raw, ok := rule["id"]; ok {
745				var ruleID string
746				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
747					where = "rule " + ruleID
748				}
749			}
750			raw, ok := rule["requiresABI"]
751			if !ok {
752				continue
753			}
754			var token any
755			if err := json.Unmarshal(raw, &token); err != nil {
756				return errCorrupt("report " + id + " archive is corrupt: " + where + ": requiresABI must be a boolean")
757			}
758			if _, isBool := token.(bool); !isBool {
759				return errCorrupt("report " + id + " archive is corrupt: " + where + ": requiresABI must be a boolean")
760			}
761		}
762		return nil
763	}
764	
765	// loadStoredReport parses archive bytes for id and fully validates them.
766	func loadStoredReport(data []byte, id string) (Report, error) {
767		// Read-side counterpart of the submission character gate in
768		// ParseAuditInput. As with a repeated member, json.Unmarshal silently
769		// rewrites an invalid UTF-8 byte and an unpaired or wrongly ordered
770		// surrogate escape into U+FFFD, so an archive whose note and evidence both
771		// carried the substitution character could have those two spots changed to
772		// lone surrogate escapes and still decode to byte-identical content: the
773		// recomputed id and the rule/finding evidence comparison would then pass on
774		// the rewritten copy. Every raw string literal is checked first — member
775		// names and values, at every depth, inside unknown extension members too —
776		// and the whole archive is corrupt when any character is illegal, whatever
777		// id the rewritten content would compute.
778		if charErr := validateJSONCharacters(data); charErr != nil {
779			return Report{}, characterArchiveError(id, charErr)
780		}
781		// Read-side counterpart of the submission check: json.Unmarshal silently
782		// keeps the last value for a repeated member, so an archive that writes a
783		// rule status as 发现缺陷 and then 通过 would decode to whichever came
784		// last. The recomputed id and the rule/finding correspondence all operate
785		// on that last-wins value and could therefore pass, accepting an archive
786		// with two conflicting conclusions. Any repeated member in any object
787		// makes the archive corrupt, regardless of the last value.
788		if dup := findDuplicateJSONMember(data); dup != nil {
789			return Report{}, duplicateArchiveError(id, data, dup)
790		}
791		strict, err := strictReportJSON(data)
792		if err != nil {
793			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
794		}
795		// Check the formal requiresABI member against its raw JSON token before
796		// decoding into the Go bool below; otherwise a null value would silently
797		// become the zero value false and could pass every later check, including
798		// the content id, as if the archive had explicitly said false.
799		if err := validateArchiveRequiresABI(strict, id); err != nil {
800			return Report{}, err
801		}
802		var r Report
803		if err := json.Unmarshal(strict, &r); err != nil {
804			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
805		}
806		if r.ReportID != id {
807			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
808		}
809		if err := validStoredReport(r); err != nil {
810			return Report{}, err
811		}
812		return r, nil
813	}
814	
815	// saveReportHook, when set, is invoked after the archive existence check and
816	// before the atomic publish. It lets tests simulate another process racing to
817	// claim the same report id.
818	var saveReportHook func(finalPath string)
819	
820	// SaveReport persists a report under the store directory. The store is safe
821	// for concurrent writers: identical reports share one file and all
822	// submissions succeed, different reports never overwrite each other, and
823	// readers only ever observe complete files. A submission is fully validated
824	// before any store operation, so an invalid report creates no store and no
825	// files. Every string in a directly constructed report must be valid UTF-8:
826	// json.Marshal would otherwise rewrite an invalid byte to U+FFFD while the
827	// content-addressed id matched the rewritten copy, reporting success for an
828	// archive whose text differs from the caller's; such a report is rejected as
829	// an input error before the store directory is touched. A pre-existing file
830	// with the same id must be a valid archive of the same report; a corrupted
831	// archive makes the submission fail while keeping the original file, even
832	// when the corruption appears only during the save. The first successfully
833	// archived bytes are never replaced by later submissions.
834	func SaveReport(dir string, r Report) error {
835		if err := validateSubmittedText(r); err != nil {
836			return err
837		}
838		if err := validSubmittedReport(r); err != nil {
839			return err
840		}
841		if err := os.MkdirAll(dir, 0o755); err != nil {
842			return err
843		}
844		finalPath := filepath.Join(dir, r.ReportID+".json")
845		if existing, err := os.ReadFile(finalPath); err == nil {
846			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
847				return err
848			}
849			return nil
850		} else if !os.IsNotExist(err) {
851			return err
852		}
853		data, err := json.Marshal(r)
854		if err != nil {
855			return err
856		}
857		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
858		if err != nil {
859			return err
860		}
861		tmpPath := tmp.Name()
862		cleanup := func() { os.Remove(tmpPath) }
863		if _, err := tmp.Write(data); err != nil {
864			tmp.Close()
865			cleanup()
866			return err
867		}
868		if err := tmp.Sync(); err != nil {
869			tmp.Close()
870			cleanup()
871			return err
872		}
873		if err := tmp.Close(); err != nil {
874			cleanup()
875			return err
876		}
877		if saveReportHook != nil {
878			saveReportHook(finalPath)
879		}
880		if err := os.Link(tmpPath, finalPath); err != nil {
881			cleanup()
882			if os.IsExist(err) {
883				existing, readErr := os.ReadFile(finalPath)
884				if readErr != nil {
885					return readErr
886				}
887				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
888					return err
889				}
890				return nil
891			}
892			return err
893		}
894		cleanup()
895		return nil
896	}
897	
898	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
899	// hex characters; missing, corrupted or tampered archives produce a clear
900	// error. The store is only read, never created or modified.
901	func LoadReport(dir, id string) (Report, error) {
902		if !validReportID(id) {
903			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
904		}
905		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
906		if err != nil {
907			if os.IsNotExist(err) {
908				return Report{}, errNotFound("report " + id + " not found")
909			}
910			return Report{}, err
911		}
912		return loadStoredReport(data, id)
913	}
914	
915	type errNotFound string
916	
917	func (e errNotFound) Error() string { return string(e) }
918	
919	type errCorrupt string
920	
921	func (e errCorrupt) Error() string { return string(e) }
922

