208	func TestLoadReportNullRequiresABIDefectBindingStillRejected(t *testing.T) {
209		dir := t.TempDir()
210		id := writeArchiveWithRuleRequiresABI(t, dir, oneDefectFixture(), "r-bad", `"requiresABI":null`)
211		// 直接核对：读出的（未经类型关的）缺陷绑定与规则一一吻合，唯一的不
212		// 合法点就是 requiresABI 的 null。
213		data, _ := os.ReadFile(filepath.Join(dir, id+".json"))
214		strict, _ := strictReportJSON(data)
