225	// --- 兼容行为：省略仍为 false；显式 true/false 按原值读回，标识与证据不变 ---
226	
227	func TestLoadReportRequiresABIOmittedAndExplicitValuesPreserved(t *testing.T) {
228		dir := t.TempDir()
