230		// 省略 r-pass 的 requiresABI：读回 false，且与显式 false 的归档同标识。
231		omittedID := writeArchiveWithRuleRequiresABI(t, dir, oneDefectFixture(), "r-pass", ``)
232		omitted, err := LoadReport(dir, omittedID)
233		if err != nil {
