240			t.Fatalf("omitted and explicit false must share the report id:\n%s\n%s", omittedID, want)
241		}
242	
243		// 显式 true 按原值读回，规则状态与归属保持不变。
244		withTrue := oneDefectFixture()
245		withTrue.Rules[0].RequiresABI = true
246		trueID := writeReportWithFreshID(t, dir, withTrue)
247		loadedTrue, err := LoadReport(dir, trueID)
248		if err != nil {
