290	// --- 正式成员非法时，旁边的大小写变体即使写了合法布尔值也不能挽救（前后两种位置） ---
291	
292	func TestLoadReportRequiresABIVariantCannotRescueFormalNull(t *testing.T) {
293		for _, pos := range []string{"before", "after"} {
294			t.Run(pos, func(t *testing.T) {
295				dir := t.TempDir()
296				fragment := `"requiresABI":null,"RequiresABI":false`
297				if pos == "before" {
298					fragment = `"RequiresABI":false,"requiresABI":null`
299				}
300				id := writeArchiveWithRuleRequiresABI(t, dir, oneDefectFixture(), "r-pass", fragment)
301				expectCorruptRequiresABILoad(t, dir, id, "r-pass")
302			})
303		}
304	}
