306	// --- Unicode 转义写出的正式名称遵守同一布尔规则 ---
307	
308	func TestLoadReportEscapedRequiresABINameFollowsSameRule(t *testing.T) {
309		// "\u0072equiresABI" 解码后就是 requiresABI：null 同样判为损坏。
310		dir := t.TempDir()
311		nullID := writeArchiveWithRuleRequiresABI(t, dir, oneDefectFixture(), "r-pass",
312			`"`+jsonEscapedR+`equiresABI":null`)
313		expectCorruptRequiresABILoad(t, dir, nullID, "r-pass")
314	
315		// 转义写法携带合法 true 时，与直接书写 true 的报告标识一致并按原值读回。
316		escapedTrueID := writeArchiveWithRuleRequiresABI(t, dir, oneDefectFixture(), "r-pass",
317			`"`+jsonEscapedR+`equiresABI":true`)
318		loadedEscaped, err := LoadReport(dir, escapedTrueID)
319		if err != nil {
320			t.Fatalf("escaped spelling with a legal boolean must load: %v", err)
321		}
322		if !loadedEscaped.Rules[0].RequiresABI {
323			t.Fatal("escaped requiresABI:true must read back as true")
324		}
