331	
332	// --- 拒绝时不创建任何额外文件，重复读取始终拒绝 ---
333	
334	func TestLoadReportNullRequiresABINoFilesAndRepeatedRejection(t *testing.T) {
335		dir := t.TempDir()
336		id := writeArchiveWithRuleRequiresABI(t, dir, oneDefectFixture(), "r-none", `"requiresABI":null`)
337		before, err := os.ReadDir(dir)
338		if err != nil {
339			t.Fatal(err)
340		}
341		for i := 0; i < 2; i++ {
