354	
355	// --- diff：任一侧归档含非法 requiresABI 都整体失败，不输出局部差异，不把
356	// 被洗成 false 的规则拿去比较“无变化”或“规则变化” ---
357	
358	func TestDiffStoreRejectsBadRequiresABIEitherSide(t *testing.T) {
359		dir := t.TempDir()
360		good := oneDefectFixture()
361		goodID := writeReportWithFreshID(t, dir, good)
362	
363		// 另一侧是另一份合法报告（多一条规则），损坏后落盘；null 会被洗成
364		// false，所以损坏归档与合法归档共用同一标识，先留一份干净字节便于恢复。
365		other := oneDefectFixture()
366		other.Rules = append(other.Rules,
367			ReportRule{ID: "r-extra", Kind: "static", Severity: "info", Invariant: "inv-extra", Version: "9", Status: StatusPass})
368		otherID := writeReportWithFreshID(t, dir, other)
369		cleanOther, err := os.ReadFile(filepath.Join(dir, otherID+".json"))
370		if err != nil {
371			t.Fatal(err)
372		}
373		badID := writeArchiveWithRuleRequiresABI(t, dir, other, "r-extra", `"requiresABI":null`)
374		if badID != otherID {
375			t.Fatalf("test setup: null launders to false, so the id must stay %q, got %q", otherID, badID)
376		}
377		badBytes, err := os.ReadFile(filepath.Join(dir, badID+".json"))
378		if err != nil {
379			t.Fatal(err)
380		}
381	
382		for _, tc := range []struct {
383			name   string
384			before string
385			after  string
386			named  string
387		}{
388			{"second report corrupt", goodID, badID, badID},
389			{"first report corrupt", badID, goodID, badID},
390		} {
391			t.Run(tc.name, func(t *testing.T) {
392				if data, _ := os.ReadFile(filepath.Join(dir, badID+".json")); !bytes.Contains(data, []byte(`"requiresABI":null`)) {
393					t.Fatalf("subtest start: archive already repaired:\n%s", data)
394				}
395				diff, err := DiffStore(dir, tc.before, tc.after)
396				if data, _ := os.ReadFile(filepath.Join(dir, badID+".json")); !bytes.Contains(data, []byte(`"requiresABI":null`)) {
397					t.Fatalf("subtest end: DiffStore rewrote the archive:\n%s", data)
398				}
399				if err == nil {
400					t.Fatalf("diff must fail when a side carries a bad requiresABI, got %+v", diff)
401				}
402				var ec errCorrupt
403				if !errors.As(err, &ec) {
404					t.Fatalf("expected errCorrupt, got %T: %v", err, err)
405				}
406				if !strings.Contains(err.Error(), "r-extra") ||
407					!strings.Contains(err.Error(), "requiresABI must be a boolean") ||
408					!strings.Contains(err.Error(), tc.named) {
409					t.Fatalf("error must name the report, rule and boolean requirement: %v", err)
410				}
411				if !reflect.DeepEqual(diff, DiffResult{}) {
412					t.Fatalf("failed diff must return the zero result, got %+v", diff)
413				}
414			})
415		}
416	
417		// 失败的比较不得修复、覆盖损坏侧归档：重复失败后损坏字节原样保留。
418		for i := 0; i < 2; i++ {
419			if _, err := DiffStore(dir, goodID, badID); err == nil {
420				t.Fatal("diff against the corrupt side must keep failing")
421			}
422			kept, err := os.ReadFile(filepath.Join(dir, badID+".json"))
423			if err != nil {
424				t.Fatal(err)
425			}
426			if !bytes.Contains(kept, []byte(`"requiresABI":null`)) {
427				t.Fatalf("failed diff must leave the corrupt archive untouched:\n%s", kept)
428			}
429		}
430	
431		// 恢复另一侧后比较成功：证明失败只来自类型关，而非报告对本身有问题，
432		// 且成功的比较同样不重写归档。
433		if err := os.WriteFile(filepath.Join(dir, otherID+".json"), cleanOther, 0o644); err != nil {
434			t.Fatal(err)
435		}
436		if _, err := DiffStore(dir, goodID, otherID); err != nil {
437			t.Fatalf("restored archive must diff successfully: %v", err)
438		}
439		afterRestore, err := os.ReadFile(filepath.Join(dir, otherID+".json"))
440		if err != nil {
441			t.Fatal(err)
442		}
443		if !bytes.Equal(afterRestore, cleanOther) {
444			t.Fatal("successful diff must not rewrite the archive")
445		}
446		// 损坏阶段的字节与干净字节确实不同，保证前面的保留断言有效。
447		if bytes.Equal(badBytes, cleanOther) {
448			t.Fatal("test setup: the mutated archive must differ from the clean one")
449		}
450	}
451	
452	// --- audit 保存遇到同标识已有损坏归档：不能被当成保存成功，原文件保留 ---
453	
454	func TestSaveReportBadRequiresABIExistingArchiveFails(t *testing.T) {
